content:
/* ============================================================
   命定之诗 · 路线图显示  map-r11
   ------------------------------------------------------------
   把地理路线画到状态栏的地图面板上。

   数据源（按优先级自动选择，只读不写）：
     ① chat 变量 poem_geo —— 「地理注入」改版补丁，本卡以它为准
        p:[id,name,level,imp,brief,parent,polity,nx,ny,detail]
        e:[from,to,[[transport,days,terrain,direction,distKm],...],via]
        带 level / polity / 坐标 / 配色 / 线型 / 线宽 / 拐点
     ② chat 变量 runtime_geo_compact_data —— 原版 MVU 卡自带，没装补丁时兜底
        { version, places:[{id,name,parent,keywords,description,importance}],
          edges:[{from,to,segments:[{transport,days,terrain,direction}]}] }
     两者的差异在 normalizeGeo() 里抹平，下游逻辑只认统一结构。

   坐标与当前位置：
     · 坐标来自 character 变量 map_markers（原版自带 / 地图覆盖脚本写入）
       按地名 + 别名 + 括号归一化 + 前缀匹配 join 到地点
     · 当前位置读「这张地图所在楼层」的 stat_data.世界.地点（楼层变量），
       不是聊天变量 —— 回看旧楼层时显示的是那一层的位置，不会被最新消息盖掉

   做法（已用 PoC 验证）：
     · OpenSeadragon 对这张图只做「统一缩放 + 平移」
     · 读若干标记元素的 left/top ↔ 它们的 nx/ny，即可反解 k / ox / oy
     · 于是任意 nx/ny 都能精确落到画布像素，不需要拿到 OSD 的 viewer 对象

   性质：
     · 不改任何变量、不改角色卡 / 世界书 / 聊天记录
     · 只往地图画布里插一个自己的 SVG 层，并在右下角放一个面板
     · 拔掉脚本（开关点灰 + 刷新）即完全消失，无残留

   依赖：
     · chat 变量 poem_geo（地理注入补丁）；没有时退回 runtime_geo_compact_data
     · character 变量 map_markers（角色卡自带）
     · 楼层变量 stat_data.世界.地点（当前位置）
   ============================================================ */
(() => {
  'use strict';

  const TAG = '[GEO-ROUTE]';
  const VERSION = 'map-r14';
  const IMG_W = 4864, IMG_H = 2774;

  // 视觉参数
  const LINE_W = 2.2;        // 路线基础线宽（屏幕像素）
  const GAP_PX = 2;          // 并排线之间的黑缝
  const HALO_PX = 1.0;       // 整束线的外描边（1px 黑边）
  const HIT_PX = 10;         // 鼠标命中路线的容差
  const HERE_NUDGE = { x: -8, y: 0 };   // 所在地标记自己的偏移，与路线锚点完全独立
  const PANEL_POS = 'br';                // 面板位置：br 右下 | bl 左下

  // 地名 ↔ 地图标记名 的差异。
  // 原版数据（places.yaml 有 marker_id，但 compact 没带出来）里有 5 处；
  // 「永冻冰原（北）」这类全半角括号差异由 norm() 自动抹平，不必列。
  // 走「地图覆盖」补丁时会多出几处改名，一并兜住。
  const ALIAS = {
    '翼民圣国': '梵尼亚',
    '精灵王庭': '卢森提亚王庭',
    '冬帷林海': '冬帷林盘',
    '月隐谷原': '月隐盆地',
    '永寂雷林': '永寂密林',
    // 覆盖补丁的命名差异（存在才生效，不存在不影响）
    '圣都梵尼亚': '梵尼亚',
    '天境湖湿地': '天镜湖湿地',
    '巨大旋涡': '深海大漩涡',
    '伯恩·瑞瑟喃斯': '伯恩·瑞瑟喃斯（骸响之都）'
  };

  // 内置配色（poem_geo.colors 缺失时使用）
  const TCOL_DEFAULT = {
    '商队': '#60a5fa', '徒步': '#a3e635', '海船': '#22d3ee', '船只': '#38bdf8',
    '列车': '#f472b6', '飞空艇': '#c084fc', '传送': '#fbbf24', '特殊': '#94a3b8',
    '不适用': '#64748b', '游泳': '#34d399'
  };
  // 实际使用：内置表 + 数据里带过来的覆盖
  let TCOL = Object.assign({}, TCOL_DEFAULT);
  // 交通方式可能是复合值（原版数据里有「商队，河运」「徒步，河运」），
  // 整串查不到时逐个拆开查，取第一个认得的。
  const splitTp = (t) => String(t == null ? '' : t).split(/[，,、/／+＋]/).map(x => x.trim()).filter(Boolean);
  const pickStyle = (table, t, dflt) => {
    const k = String(t == null ? '' : t).trim();
    if (table[k] != null && table[k] !== '') return table[k];
    const parts = splitTp(k);
    for (let i = 0; i < parts.length; i++) {
      const v = table[parts[i]];
      if (v != null && v !== '') return v;
    }
    return dflt;
  };
  const tColor = (t) => pickStyle(TCOL, t, '#94a3b8');

  // 线型：poem_geo.dash 覆盖（空/缺失 = 实线）
  let DASH = {};
  const dashOf = (t) => pickStyle(DASH, t, '');

  // 线宽：poem_geo.width 覆盖（缺省用 LINE_W）
  let WIDTH = {};
  const wOf = (t) => {
    const v = pickStyle(WIDTH, t, null);
    return (v == null || !isFinite(v) || v <= 0) ? LINE_W : v;
  };

  // ── 实例注册表 ──
  // 每个脚本实例跑在自己的 iframe 里。若发消息导致 iframe 重建，
  // 实例号会 +1；若旧 iframe 没被销毁，存活数会持续累加。
  const HOST = (() => { try { return window.top || window; } catch (e) { return window; } })();
  const INST = (() => {
    try {
      HOST.__geoSeq = (HOST.__geoSeq || 0) + 1;
      HOST.__geoLive = (HOST.__geoLive || 0) + 1;
      if (!HOST.__geoBorn) HOST.__geoBorn = {};
      HOST.__geoBorn[HOST.__geoSeq] = new Date().toISOString();
      return { id: HOST.__geoSeq, live: HOST.__geoLive };
    } catch (e) { return { id: 1, live: 1 }; }
  })();
  const bootAt = Date.now();
  const heartbeat = () => {
    try {
      if (!HOST.__geoHB) HOST.__geoHB = {};
      HOST.__geoHB[INST.id] = Date.now();
    } catch (e) {}
  };

  const log = (...a) => { try { console.log('%c' + TAG + '#' + INST.id, 'color:#22d3ee;font-weight:bold', ...a); } catch (e) {} };
  const warn = (...a) => { try { console.warn('%c' + TAG, 'color:#f59e0b;font-weight:bold', ...a); } catch (e) {} };
  const num = (v) => { const n = parseFloat(v); return isFinite(n) ? n : null; };
  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g,
    (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

  // ════════════ 状态 ════════════
  const S = {
    doc: null, container: null, canvas: null, overlayHost: null,
    svg: null, panel: null, tip: null,
    markerIdx: null, geo: null, markers: null,
    geoKind: '', markerSig: '', coordStat: null, geoSourceKey: '', hasLevel: false,
    panelInfo: { msgId: null, loc: '' },  // 当前地图所属楼层：{message_id, 地点}
    places: [], byId: {}, nameToId: {}, depth: {}, adj: {}, kids: {},
    placeCoord: {},                    // placeId -> {nx, ny}
    refs: [], refEls: [], k: 0, ox: 0, oy: 0, ready: false,
    estimated: false, estSize: null,   // 加载期用「整图适配画布」先摆位，标记出来后校正
    anchor: { x: 0, y: 0 }, anchorDone: false,
    nudge: { x: 0, y: 10 },            // 实测默认值：图标相对盒子中心向下 10px
    mode: 'all',                       // hop1 | hop2 | all（默认全图）
    view: 'node',                      // node | region（区域视图按 topScope 聚合）
    hideNodes: true,                   // 区域视图下隐藏 L3+ 标记
    blockCoord: {},                    // 区块 id -> {nx, ny}（缓存）
    transportOff: new Set(),
    show: true,
    veil: 20,                          // 底图压暗强度 %（0-90）
    ui: { open: true, transportOpen: true },
    veilEl: null,
    hereEl: null,                      // 所在地图钉（DOM 层，浮在标记之上）
    built: false,                      // 是否已建过线段（不能用 segs.length 判断，
                                       // 因为「当前位置无路线」时长度恒为 0，会导致每轮重建）
    segs: [],                          // 已建好的线段记录
    currentId: null,
    lastBuild: 0, lastGeo: '', statAt: 0, tickN: 0, fastN: 0,
    diag: { containers: 0, cands: 0, candList: [], chosen: '—', layer: '—',
            refs: 0, k: 0, segs: 0, tickAt: 0 },
    lastMapSig: -1, swept: false
  };

  // ════════════ 数据层 ════════════
  // 地名比较：全半角括号 / 全角空格 / 大小写 全部抹平后再比
  function norm(s) {
    return String(s == null ? '' : s).trim().toLowerCase()
      .replace(/（/g, '(').replace(/）/g, ')')
      .replace(/[\s\u3000]+/g, '');
  }
  function splitPath(s) {
    return String(s == null ? '' : s).split(/[-－—>＞/／,，、;；\n]+/).map(norm).filter(Boolean);
  }
  // 去掉括号注释：伯恩·瑞瑟喃斯（骸响之都）→ 伯恩·瑞瑟喃斯（全半角都认）
  function stripParen(s) { return String(s == null ? '' : s).replace(/[（(][^）)]*[）)]/g, '').trim(); }

  // 选数据源：地理注入补丁（poem_geo）优先 —— 这是二创改版的权威数据，
  // 带 level / polity / 坐标 / 配色 / 拐点，地图以它为准。
  // 没装补丁的存档再退回原版 compact（少了上述字段，走推导）。
  function readGeoSource() {
    let chat = null;
    try { chat = getVariables({ type: 'chat' }) || {}; } catch (e) { return null; }
    const poem = chat.poem_geo;
    if (poem && Array.isArray(poem.p) && poem.p.length) {
      return { kind: 'poem', raw: poem };
    }
    const compact = chat.runtime_geo_compact_data;
    if (compact && Array.isArray(compact.places) && compact.places.length) {
      return { kind: 'compact', raw: compact };
    }
    return null;
  }

  // 两种数据源 → 统一结构。下游只认这个结构，不再关心数据从哪来。
  //   place: { id, name, level, importance, description{brief,detail}, parent, keywords, polity, nx, ny }
  //   edge : { from, to, importance, segments[{transport,days,terrain[],direction,distKm}], via[] }
  function normalizeGeo(src) {
    const out = {
      kind: src.kind, version: '', places: [], edges: [],
      colors: null, dash: null, width: null
    };

    if (src.kind === 'compact') {
      const d = src.raw;
      out.version = d.version == null ? '' : String(d.version);
      out.places = (d.places || []).map(p => {
        const desc = (p && p.description) || {};
        return {
          id: String(p.id),
          name: String(p.name == null ? '' : p.name),
          level: null,
          importance: p.importance == null ? 2 : (Number(p.importance) || 0),
          description: { brief: desc.brief || '', detail: desc.detail || '' },
          parent: p.parent == null ? null : String(p.parent),
          keywords: Array.isArray(p.keywords) ? p.keywords.map(String) : [],
          polity: null, nx: null, ny: null
        };
      });
      out.edges = (d.edges || []).map(e => ({
        from: String(e.from), to: String(e.to),
        importance: e.importance == null ? 2 : (Number(e.importance) || 0),
        segments: (e.segments || []).map(s => ({
          transport: s.transport == null ? '' : String(s.transport),
          days: (s.days == null || s.days === '') ? null : (isFinite(Number(s.days)) ? Number(s.days) : null),
          terrain: Array.isArray(s.terrain)
            ? s.terrain.map(String)
            : String(s.terrain == null ? '' : s.terrain).split('/').filter(Boolean),
          direction: s.direction == null ? '' : String(s.direction),
          distKm: s.distKm == null ? null : Number(s.distKm)
        })),
        via: Array.isArray(e.via) ? e.via.map(v => (
          Array.isArray(v) ? { nx: v[0], ny: v[1] } : { nx: v && v.nx, ny: v && v.ny }
        )).filter(v => isFinite(v.nx) && isFinite(v.ny)) : []
      }));
      return out;
    }

    const d = src.raw;
    out.version = d.v == null ? '' : String(d.v);
    out.places = (d.p || []).map(r => ({
      id: String(r[0]),
      name: String(r[1] == null ? '' : r[1]),
      level: r[2] == null ? null : Number(r[2]),
      importance: r[3] == null ? 2 : (Number(r[3]) || 0),
      description: { brief: r[4] || '', detail: r[9] || '' },
      parent: r[5] ? String(r[5]) : null,
      polity: !!r[6],
      nx: r[7], ny: r[8],
      keywords: []
    }));
    out.edges = (d.e || []).map(r => ({
      from: String(r[0]), to: String(r[1]),
      importance: 2,
      segments: (r[2] || []).map(x => ({
        transport: x[0] == null ? '' : String(x[0]),
        days: x[1] == null ? null : Number(x[1]),
        terrain: String(x[2] == null ? '' : x[2]).split('/').filter(Boolean),
        direction: x[3] == null ? '' : String(x[3]),
        distKm: x[4]
      })),
      via: (Array.isArray(r[3]) ? r[3] : [])
        .map(v => ({ nx: v && v[0], ny: v && v[1] }))
        .filter(v => isFinite(v.nx) && isFinite(v.ny))
    }));
    out.colors = d.colors || null;
    out.dash = d.dash || null;
    out.width = d.width || null;
    return out;
  }

  // 标记位置指纹：玩家拖动/改名/增删标记后用它判断要不要重建
  function markerSignature(markers) {
    let h = 0;
    const push = (s) => { for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0; };
    for (let i = 0; i < markers.length; i++) {
      const m = markers[i] || {};
      push(String(m.id || '') + '|' + String(m.name || '') + '|' +
           (m.position ? (m.position.nx + ',' + m.position.ny) : ''));
    }
    return markers.length + ':' + h;
  }

  function buildModel() {
    let chr = null;
    try { chr = getVariables({ type: 'character' }); } catch (e) {}
    const src = readGeoSource();
    if (!src) {
      log('没有地理数据：chat 里既没有 runtime_geo_compact_data，也没有 poem_geo');
      return false;
    }
    const markers = chr && chr.map_markers;
    if (!Array.isArray(markers) || !markers.length) {
      log('map_markers 为空 —— 角色卡变量缺失');
      return false;
    }

    const geo = normalizeGeo(src);
    S.geo = geo;
    S.geoKind = src.kind;
    S.markers = markers;
    S.markerSig = markerSignature(markers);

    // 样式：数据里带了就用（poem 系），没带就用内置表（原版）
    TCOL = Object.assign({}, TCOL_DEFAULT, (geo.colors && typeof geo.colors === 'object') ? geo.colors : {});
    DASH = (geo.dash && typeof geo.dash === 'object') ? geo.dash : {};
    WIDTH = (geo.width && typeof geo.width === 'object') ? geo.width : {};

    // 地点表
    S.places = geo.places;
    S.byId = {};
    S.nameToId = {};
    S.depth = {}; S.adj = {}; S.kids = {}; S.placeCoord = {}; S.blockCoord = {};

    geo.places.forEach(p => {
      S.byId[p.id] = p;
      S.nameToId[norm(p.name)] = p.id;
      // 标记名和地点名不一致时，把别名也登记进去，
      // 区域视图隐藏 L3+ 标记靠的就是「标记文字 → 地点 id」这条路。
      const a = ALIAS[String(p.name).trim()];
      if (a) S.nameToId[norm(a)] = p.id;
      S.adj[p.id] = [];
      S.kids[p.id] = [];
    });
    geo.places.forEach(p => {
      if (p.parent && S.byId[p.parent]) S.kids[p.parent].push(p.id);
    });

    // 层级：数据里有就用（poem 的 level），没有就按 parent 链推（原版 compact）
    const calcDepth = (id, guard) => {
      if (S.depth[id] != null) return S.depth[id];
      guard = guard || new Set();
      const p = S.byId[id];
      if (!p || !p.parent || !S.byId[p.parent] || guard.has(id)) { S.depth[id] = 0; return 0; }
      guard.add(id);
      S.depth[id] = calcDepth(p.parent, guard) + 1;
      return S.depth[id];
    };
    geo.places.forEach(p => calcDepth(p.id));
    // 数据自带 level 吗（poem_geo 有，原版 compact 没有）——区域视图的区块口径按这个分流
    S.hasLevel = geo.places.some(p => p.level != null && isFinite(p.level));
    geo.places.forEach(p => {
      const d = S.depth[p.id] || 0;
      p.depth = d;
      if (p.level == null || !isFinite(p.level)) p.level = d;
    });

    // 标记索引：原名 / 去括号名 / 标记 id 三套
    const byName = {}, byStem = {};
    S.markerById = {};
    S.placeByMarkerId = {};
    markers.forEach(m => {
      if (!m || !m.name || !m.position) return;
      const nx = num(m.position.nx), ny = num(m.position.ny);
      if (nx == null || ny == null) return;
      const rec = { nx: nx, ny: ny, id: m.id || null, name: String(m.name) };
      const k = norm(m.name);
      if (k && !byName[k]) byName[k] = rec;
      const stem = norm(stripParen(m.name));
      if (stem && !byStem[stem]) byStem[stem] = rec;
      if (rec.id) S.markerById[String(rec.id)] = rec;
    });
    S.markerIdx = byName;

    // 坐标：地点名 → 标记（原名 > 别名 > 去括号名 > 唯一前缀）
    let matched = 0, viaAlias = 0, viaStem = 0, fallback = 0;
    const miss = [];
    geo.places.forEach(p => {
      let m = byName[norm(p.name)];
      if (m) matched++;
      if (!m) {
        const a = ALIAS[String(p.name).trim()];
        if (a) { m = byName[norm(a)] || byStem[norm(stripParen(a))]; if (m) viaAlias++; }
      }
      if (!m) { m = byStem[norm(stripParen(p.name))]; if (m) viaStem++; }
      if (!m) {
        const stem = norm(stripParen(p.name));
        if (stem.length >= 2) {
          const hit = Object.keys(byStem).filter(k => k.indexOf(stem) === 0);
          if (hit.length === 1) { m = byStem[hit[0]]; viaStem++; }
        }
      }
      if (m) {
        S.placeCoord[p.id] = { nx: m.nx, ny: m.ny };
        if (m.id) S.placeByMarkerId[String(m.id)] = p.id;
      }
      else if (p.nx != null && p.ny != null) {
        S.placeCoord[p.id] = { nx: num(p.nx), ny: num(p.ny) };
        fallback++;
      } else {
        miss.push(p.name);
      }
    });
    S.coordStat = { matched: matched, alias: viaAlias, stem: viaStem, fallback: fallback, miss: miss };

    // 邻接
    geo.edges.forEach(e => {
      if (!S.adj[e.from] || !S.adj[e.to]) return;
      S.adj[e.from].push({ other: e.to, edge: e });
      S.adj[e.to].push({ other: e.from, edge: e });
    });

    log('数据就绪 [' + src.kind + ' v' + geo.version + ']：places=' + geo.places.length +
        ' edges=' + geo.edges.length + ' markers=' + markers.length +
        ' 坐标：原名 ' + matched + ' / 别名 ' + viaAlias + ' / 去括号 ' + viaStem +
        (fallback ? (' / 内置 ' + fallback) : '') +
        (miss.length ? (' / 未匹配 ' + miss.length + '：' + miss.slice(0, 6).join('、')) : ''));

    // 换数据源后旧的 currentId 可能对不上新表，强制下一轮重算
    S.currentId = null;
    S.lastGeo = '';
    S.built = false;
    return true;
  }

  // 地名匹配：照搬世界书《长途移动与地理参考》的评分口径，
  // 让地图认出来的地点和提示词认出来的是同一个（keywords 也参与）。
  function cmpKey(a, b) {
    for (let i = 0; i < a.length; i++) {
      if (a[i] !== b[i]) return a[i] > b[i] ? 1 : -1;
    }
    return 0;
  }

  function matchPlace(query) {
    const q = norm(query);
    if (!q) return null;
    const segs = splitPath(query);
    let best = null, bestKey = null;
    for (const p of S.places) {
      const pd = S.depth[p.id] || 0;
      const imp = Number(p.importance || 0);
      let key = null;
      const toks = [p.name].concat(p.keywords || []);
      for (const raw of toks) {
        const t = norm(raw);
        if (!t) continue;
        const len = t.length;
        // 地名本身命中比关键词命中更可信（否则「白石镇」会被
        // 把「白石镇」写进关键词的「白石修道院」抢走）
        const hitTier = raw === p.name ? 3 : 2;
        let score = null;
        if (q === t) score = [hitTier, pd, 4, segs.length, imp, len];
        for (let i = 0; i < segs.length; i++) {
          const s = segs[i];
          let sc = null;
          if (s === t) sc = [hitTier, pd, 3, i, imp, len];
          else if (s.indexOf(t) >= 0) sc = [hitTier, pd, 2, i, imp, len];
          if (sc && (!score || cmpKey(sc, score) > 0)) score = sc;
        }
        if (!score && q.indexOf(t) >= 0) score = [hitTier, pd, 1, -1, imp, len];
        if (!score) {
          for (let i = 0; i < segs.length; i++) {
            const s = segs[i];
            if (s.length >= 2 && t.indexOf(s) >= 0) {
              const sc = [hitTier - 1, pd, 1, i, imp, len];
              if (!score || cmpKey(sc, score) > 0) score = sc;
            }
          }
        }
        if (score && (!key || cmpKey(score, key) > 0)) key = score;
      }
      if (key && (!bestKey || cmpKey(key, bestKey) > 0)) { best = p; bestKey = key; }
    }
    return best;
  }

  // 读「这张地图所在楼层」自己的变量。
  // 状态栏是一层一个 iframe，MVU 的 stat_data 是楼层变量；
  // 用这一层的 message_id 去取，回看旧楼层时才是那一层的位置。
  //
  // 取 message_id 的两条路：
  //   ① 楼层页面自己的 getCurrentMessageId()（酒馆助手注入的全局函数）
  //   ② 兜底：顺着 iframe 往上找 <div class="mes" mesid="N">
  function messageIdFromDom(win) {
    try {
      let el = win.frameElement;
      for (let i = 0; el && i < 14; i++) {
        const v = el.getAttribute && el.getAttribute('mesid');
        if (v != null && v !== '' && isFinite(Number(v))) return Number(v);
        el = el.parentElement;
      }
    } catch (e) {}
    return null;
  }

  function panelState(win) {
    let msgId = null;
    try {
      if (win && typeof win.getCurrentMessageId === 'function') msgId = win.getCurrentMessageId();
    } catch (e) { msgId = null; }
    if (typeof msgId !== 'number' || msgId < 0) msgId = null;
    if (msgId == null) msgId = messageIdFromDom(win);

    const pick = (v) => {
      try {
        const st = v && v.stat_data;
        let loc = st && st.世界 && st.世界.地点;
        if (Array.isArray(loc)) loc = loc.join('-');
        return typeof loc === 'string' ? loc.trim() : '';
      } catch (e) { return ''; }
    };

    // 拿到楼层号就只认这一层：这一层没有 stat_data 就显示「未识别」，
    // 不拿最新楼层来凑 —— 否则回看旧楼层会显示成最新位置，正是要避免的。
    let loc = '';
    if (msgId != null) {
      try { loc = pick(getVariables({ type: 'message', message_id: msgId })); } catch (e) {}
    } else {
      try { loc = pick(getVariables({ type: 'message', message_id: 'latest' })); } catch (e) {}
      if (!loc) {
        try { loc = pick(getVariables({ type: 'chat' })); } catch (e) {}
      }
    }
    return { msgId: msgId, loc: loc };
  }

  function readCurrent() {
    const loc = S.panelInfo ? S.panelInfo.loc : '';
    if (loc) {
      const p = matchPlace(loc);
      if (p) return p.id;
    }
    // 只有拿不到楼层号时才退回注入脚本解析好的当前节点：
    // poem_geo_state 是聊天级（等于最新楼层），拿它填旧楼层会张冠李戴。
    if (!S.panelInfo || S.panelInfo.msgId == null) {
      try {
        const st = (getVariables({ type: 'chat' }) || {}).poem_geo_state;
        if (st && st.nodeId && S.byId[st.nodeId]) return st.nodeId;
      } catch (e) { void e; }
    }
    return null;
  }

  // ════════════ 地图发现 ════════════
  // 只有「状态栏 → 地图页签」里的那张图才该画路线。
  // 自定义开局页（起始地点选择）也用 OpenSeadragon 显示同一张世界地图，
  // 但它没有 data-page="map"，根节点是 .creator-app / 地图块是 .location-map —— 排除掉。
  function classifyMapPage(canvas) {
    let el = canvas, depth = 0, isStatus = false, isOther = false;
    while (el && depth++ < 16) {
      try {
        const page = el.getAttribute && el.getAttribute('data-page');
        if (page) { if (page === 'map') isStatus = true; else isOther = true; }
        const cls = el.classList;
        if (cls && (cls.contains('creator-app') || cls.contains('location-map'))) isOther = true;
      } catch (e) {}
      el = el.parentElement;
    }
    return { isStatus: isStatus, isOther: isOther };
  }

  function findMap() {
    const wins = [], docs = [];
    const seenW = new Set(), seenD = new Set();
    const pushW = (w) => { try { if (w && !seenW.has(w)) { seenW.add(w); wins.push(w); } } catch (e) {} };
    let topW = window;
    try { if (window.top) topW = window.top; } catch (e) {}
    pushW(topW); pushW(window);
    for (let i = 0; i < wins.length && i < 40; i++) {
      let fr = null;
      try { fr = wins[i].frames; } catch (e) { continue; }
      if (!fr) continue;
      for (let k = 0; k < fr.length && k < 40; k++) pushW(fr[k]);
    }
    wins.forEach(w => {
      let d = null; try { d = w.document; } catch (e) {}
      if (d && !seenD.has(d)) { seenD.add(d); docs.push(d); }
    });
    // 一个页面上可能有多个 OpenSeadragon 实例：
    //   主图 / 右下角导航缩略图 / 旧消息面板里的地图 / 新消息面板里的地图。
    // 只比面积是不够的——两张状态面板的地图尺寸往往一模一样，
    // 这时会取到先枚举到的旧面板，路线和面板就画到用户没看的那张上。
    // 所以换算成「在顶层窗口里真实可见的像素面积」再比。
    //
    // 这里直接按 canvas 找，而不是按标记找：地图刚打开、图片还在加载时
    // 还没有任何标记元素，但 canvas 已经存在 —— 只有这样才能在加载期就先把线画好。
    const cands = [];
    const seenCanvas = new Set();
    docs.forEach((d, di) => {
      let list = [];
      try { list = Array.from(d.querySelectorAll('.openseadragon-canvas')); } catch (e) { return; }
      for (const canvas of list) {
        if (seenCanvas.has(canvas)) continue;
        seenCanvas.add(canvas);
        if (!canvas.isConnected) continue;
        // 跳过右下角的小地图（导航缩略图里的 canvas）
        let anc = canvas.parentElement, isNav = false, g = 0;
        while (anc && g++ < 6) {
          if (anc.classList && anc.classList.contains('openseadragon-navigator')) { isNav = true; break; }
          anc = anc.parentElement;
        }
        if (isNav) continue;
        // 状态栏地图无条件收；其它页（自定义开局）除非既不像别页也不像状态栏，才放过
        const page = classifyMapPage(canvas);
        if (!page.isStatus && page.isOther) continue;
        const container = canvas.parentElement;
        if (!container) continue;
        let r = null;
        try { r = canvas.getBoundingClientRect(); } catch (e) {}
        if (!r || r.width * r.height <= 0) continue;
        // 标记层可能还没出来（加载中），此时 overlayHost 为 null
        let host = null;
        try {
          const wrap = canvas.querySelector('.openseadragon-overlay-wrapper');
          if (wrap && wrap.parentElement) host = wrap.parentElement;
        } catch (e) {}
        let Win = null;
        try { Win = d.defaultView; } catch (e) {}
        const vis = visibleAreaInTop(Win, r);
        cands.push({
          doc: d, container, canvas, overlayHost: host,
          area: r.width * r.height, vis: vis, docIndex: di,
          screen: rectInTop(Win, r)
        });
      }
    });
    if (!cands.length) return null;

    cands.sort((a, b) => (b.vis - a.vis) || (b.docIndex - a.docIndex) || (b.area - a.area));
    let best = cands[0];

    // 滞回：当前挂载点还活着时，只有别的地图「明显更可见」才切过去。
    // 否则滚动过程中可见面积轻微波动会让它来回重挂、闪烁。
    const cur = S.canvas ? cands.find(c => c.canvas === S.canvas) : null;
    if (cur && cur.canvas && cur.canvas.isConnected && best.canvas !== cur.canvas) {
      if (cur.vis === 0 && best.vis === 0) {
        best = cur;                                  // 都看不见，保持不动
      } else if (cur.vis > 0 && best.vis < cur.vis * 1.4) {
        best = cur;                                  // 优势不足 40%，不切
      }
    }
    if (S.diag) {
      S.diag.cands = cands.length;
      S.diag.candList = cands.slice(0, 4).map(c =>
        'doc' + c.docIndex + ' ' + Math.round(c.screen.x) + ',' + Math.round(c.screen.y) +
        ' ' + Math.round(c.canvas.clientWidth) + 'x' + Math.round(c.canvas.clientHeight) +
        ' 可见' + Math.round(c.vis));
    }
    // 只在「选中的地图发生变化」时打日志（滚动引起的面积波动不刷屏）
    if (best.docIndex !== S.lastMapSig) {
      S.lastMapSig = best.docIndex;
      log('地图候选 ' + cands.length + ' 张：' +
          cands.slice(0, 4).map(c => '{doc' + c.docIndex + ' 可见' + Math.round(c.vis) + '}').join(' ') +
          ' → 选中 doc' + best.docIndex);
    }
    return best;
  }

  // 把某个 iframe 内元素的 rect 换算到「顶层窗口」坐标系
  function rectInTop(win, rect) {
    let x = rect.left, y = rect.top, w = win, guard = 0;
    while (w && w !== window.top && guard++ < 12) {
      let fe = null;
      try { fe = w.frameElement; } catch (e) { break; }
      if (!fe) break;
      let r = null;
      try { r = fe.getBoundingClientRect(); } catch (e) { break; }
      x += r.left; y += r.top;
      let pd = null;
      try { pd = fe.ownerDocument; } catch (e) { break; }
      w = pd && pd.defaultView;
    }
    return { x: x, y: y, w: rect.width, h: rect.height };
  }

  // 与顶层视口的相交面积（用户真正看得见多少）
  function visibleAreaInTop(win, rect) {
    let r = null;
    try { r = rectInTop(win, rect); } catch (e) { return 0; }
    let vw = 0, vh = 0;
    try {
      const t = window.top || window;
      vw = t.innerWidth || 0; vh = t.innerHeight || 0;
    } catch (e) {
      vw = window.innerWidth || 0; vh = window.innerHeight || 0;
    }
    if (!vw || !vh) return r.w * r.h;
    const ix = Math.max(0, Math.min(r.x + r.w, vw) - Math.max(r.x, 0));
    const iy = Math.max(0, Math.min(r.y + r.h, vh) - Math.max(r.y, 0));
    return ix * iy;
  }

  // ════════════ 锚点：找标记里的图标子元素 ════════════
  function iconOffsetOf(wrap, Win) {
    let icon = null;
    try {
      const kids = Array.from(wrap.children);
      for (const k of kids) {
        const cs = Win.getComputedStyle(k);
        if (cs && cs.backgroundImage && cs.backgroundImage !== 'none') { icon = k; break; }
      }
      if (!icon) icon = wrap.querySelector('img,svg,i');
      if (!icon && kids.length) {
        // 退而求其次：取最小的那个子元素
        let best = null, bestArea = Infinity;
        kids.forEach(k => {
          const r = k.getBoundingClientRect();
          const area = r.width * r.height;
          if (area > 0 && area < bestArea) { bestArea = area; best = k; }
        });
        icon = best;
      }
    } catch (e) { icon = null; }
    if (!icon) return null;
    try {
      const wr = wrap.getBoundingClientRect();
      const ir = icon.getBoundingClientRect();
      if (!wr.width || !ir.width) return null;
      return {
        x: (ir.left + ir.width / 2) - (wr.left + wr.width / 2),
        y: (ir.top + ir.height / 2) - (wr.top + wr.height / 2)
      };
    } catch (e) { return null; }
  }

  function median(arr) {
    if (!arr.length) return 0;
    const a = arr.slice().sort((x, y) => x - y);
    const m = Math.floor(a.length / 2);
    return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2;
  }

  // ════════════ 参考点与变换 ════════════
  // 原版前端给每个标记元素写了 data-marker-id，比读文字稳（玩家改名也不影响）。
  function markerIdOf(el) {
    try {
      if (el.dataset && el.dataset.markerId) return String(el.dataset.markerId);
      const inner = el.querySelector ? el.querySelector('[data-marker-id]') : null;
      if (inner && inner.dataset && inner.dataset.markerId) return String(inner.dataset.markerId);
    } catch (e) {}
    return '';
  }

  // 只在「地图元素变化时」重建一次：挑 4 个最分散的标记，缓存元素引用。
  // 之后每帧只读它们的 left/top（4 次字符串解析），开销可忽略。
  function setupRefs() {
    const host = S.overlayHost, doc = S.doc;
    if (!host || !doc) return [];
    const Win = doc.defaultView;
    const wraps = Array.from(host.querySelectorAll('.openseadragon-overlay-wrapper'));
    const all = [], offsX = [], offsY = [];
    wraps.forEach(el => {
      const name = (el.textContent || '').trim();
      const mid = markerIdOf(el);
      const m = (mid && S.markerById && S.markerById[mid]) || S.markerIdx[norm(name)];
      if (!m) return;
      all.push({
        el, name, nx: m.nx, ny: m.ny,
        hw: (el.offsetWidth || 18) / 2,
        hh: (el.offsetHeight || 18) / 2
      });
      if (!S.anchorDone) {
        const off = iconOffsetOf(el, Win);
        if (off) { offsX.push(off.x); offsY.push(off.y); }
      }
    });
    if (!S.anchorDone) {
      S.anchor.x = median(offsX);
      S.anchor.y = median(offsY);
      S.anchorDone = true;
      log('锚点：图标相对盒子中心的偏移 x=' + S.anchor.x.toFixed(1) +
          ' y=' + S.anchor.y.toFixed(1) + '（样本 ' + offsX.length + '）');
    }
    if (all.length < 2) { S.refEls = all; return all; }
    const pick = new Set();
    const byNx = all.slice().sort((a, b) => a.nx - b.nx);
    const byNy = all.slice().sort((a, b) => a.ny - b.ny);
    pick.add(byNx[0]); pick.add(byNx[byNx.length - 1]);
    pick.add(byNy[0]); pick.add(byNy[byNy.length - 1]);
    S.refEls = Array.from(pick);
    log('参考点 ' + S.refEls.length + ' 个：' + S.refEls.map(r => r.name).join('、'));
    return S.refEls;
  }

  // 每帧调用：只读缓存元素的 left/top
  function collectRefs() {
    // 地图重绘会换掉标记元素，此时必须重新挑选参考点
    if (S.refEls.some(r => !r.el.isConnected)) {
      S.refEls = [];
      return [];
    }
    return S.refEls.map(r => {
      r.left = num(r.el.style.left);
      r.top = num(r.el.style.top);
      return r;
    }).filter(r => r.left != null && r.top != null);
  }

  function solveTransform(refs) {
    if (!refs || refs.length < 2) return false;
    const pts = refs.map(r => ({
      u: r.nx * IMG_W, v: r.ny * IMG_H,
      X: r.left + r.hw, Y: r.top + r.hh
    }));
    const n = pts.length;
    const mu = pts.reduce((s, p) => s + p.u, 0) / n;
    const mv = pts.reduce((s, p) => s + p.v, 0) / n;
    const mX = pts.reduce((s, p) => s + p.X, 0) / n;
    const mY = pts.reduce((s, p) => s + p.Y, 0) / n;
    let nu = 0, de = 0;
    pts.forEach(p => {
      nu += (p.u - mu) * (p.X - mX) + (p.v - mv) * (p.Y - mY);
      de += (p.u - mu) * (p.u - mu) + (p.v - mv) * (p.v - mv);
    });
    if (!de) return false;
    const k = nu / de;
    if (!isFinite(k) || Math.abs(k) < 1e-9) return false;
    S.k = k; S.ox = mX - k * mu; S.oy = mY - k * mv;
    return true;
  }

  // 加载期的兜底：地图刚打开、标记还没渲染时，OSD 一定是「整图适配画布 + 居中」。
  // 只要知道画布尺寸和地图长宽比，就能先把线摆到正确位置；
  // 标记一出来就切回反解出来的精确值。
  const MAP_ASPECT = IMG_W / IMG_H;   // 三档底图同比例
  function estimateTransform() {
    const canvas = S.canvas;
    if (!canvas) return false;
    const W = canvas.clientWidth || canvas.offsetWidth || 0;
    const H = canvas.clientHeight || canvas.offsetHeight || 0;
    if (!W || !H) return false;
    if (S.estimated && S.estSize && S.estSize.w === W && S.estSize.h === H) return true;
    const fitW = Math.min(W, H * MAP_ASPECT);
    const fitH = fitW / MAP_ASPECT;
    const k = fitW / IMG_W;
    if (!isFinite(k) || k <= 0) return false;
    S.k = k;
    S.ox = (W - fitW) / 2;
    S.oy = (H - fitH) / 2;
    S.estSize = { w: W, h: H };
    return true;
  }

  // 图像坐标 → 画布像素（纯换算，不含任何偏移）
  function imgToRawPx(u, v) {
    return [S.k * u + S.ox, S.k * v + S.oy];
  }
  // 路线用：纯换算 + 路线锚点 + 手动微调
  function imgToCanvasPx(u, v) {
    return [
      S.k * u + S.ox + S.anchor.x + S.nudge.x,
      S.k * v + S.oy + S.anchor.y + S.nudge.y
    ];
  }
  function toCanvas(nx, ny) {
    return imgToCanvasPx(nx * IMG_W, ny * IMG_H);
  }

  // ════════════ 可见路线集合 ════════════
  function visiblePairs() {
    const out = [];
    const seen = {};
    const cur = S.currentId;

    const push = (e) => {
      if (!S.placeCoord[e.from] || !S.placeCoord[e.to]) return;
      const key = e.from < e.to ? e.from + '|' + e.to : e.to + '|' + e.from;
      if (seen[key]) return;
      seen[key] = true;
      out.push({ a: e.from, b: e.to });
    };

    if (S.mode === 'all' || !cur) {
      S.geo.edges.forEach(push);
      return out;
    }
    const allowed = {};
    allowed[cur] = true;
    if (S.mode === 'hop2') {
      (S.adj[cur] || []).forEach(x => { allowed[x.other] = true; });
    }
    S.geo.edges.forEach(e => {
      if (S.mode === 'hop1') {
        if (e.from === cur || e.to === cur) push(e);
      } else {
        if (allowed[e.from] || allowed[e.to]) push(e);
      }
    });
    return out;
  }

  // ════════════ 区块（区域视图用） ════════════
  // 数据里有 level 时（poem_geo 补丁）沿用改版口径：
  //   最近 L2 区块 → 最近 L1 政权 → L0，跟「地理注入」的区块划分一致。
  // 没有 level 时（原版 compact）退回 topScope：往上走到 parent 是大陆的那一层。
  function blockOf(id) {
    if (S.hasLevel) {
      let x = id, g = 0;
      while (x && S.byId[x] && g++ < 40) { if (S.byId[x].level === 2) return x; x = S.byId[x].parent; }
      x = id; g = 0;
      while (x && S.byId[x] && g++ < 40) {
        if (S.byId[x].level === 1 && S.byId[x].polity) return x;
        x = S.byId[x].parent;
      }
      x = id; g = 0;
      while (x && S.byId[x] && g++ < 40) { if (S.byId[x].level === 0) return x; x = S.byId[x].parent; }
      return null;
    }
    let cur = S.byId[id], guard = 0;
    const seen = {};
    while (cur && guard++ < 40 && !seen[cur.id]) {
      seen[cur.id] = 1;
      if (!cur.parent || cur.parent === 'continent') return cur.id;
      const par = S.byId[cur.parent];
      if (!par) return cur.id;
      cur = par;
    }
    return cur ? cur.id : null;
  }

  // 区块坐标：自身有标记就用标记，否则取其子树所有节点的坐标平均
  function blockCoord(bid) {
    if (S.blockCoord[bid]) return S.blockCoord[bid];
    const c = S.placeCoord[bid];
    if (c && c.nx != null && c.ny != null) { S.blockCoord[bid] = c; return c; }
    let sx = 0, sy = 0, n = 0;
    const stack = (S.kids[bid] || []).slice(), guard = {};
    while (stack.length && n < 600) {
      const x = stack.pop();
      if (guard[x]) continue; guard[x] = 1;
      const cc = S.placeCoord[x];
      if (cc && cc.nx != null && cc.ny != null) { sx += cc.nx; sy += cc.ny; n++; }
      (S.kids[x] || []).forEach(y => stack.push(y));
    }
    if (!n) return null;
    const out = { nx: sx / n, ny: sy / n };
    S.blockCoord[bid] = out;
    return out;
  }

  // ════════════ 折线工具 ════════════
  // 一条边可能有拐点（e.via），顶点序列 = [起点, ...拐点, 终点]
  function buildPts(A, B, edges) {
    const out = [[A.nx * IMG_W, A.ny * IMG_H]];
    let via = [];
    for (let i = 0; i < edges.length; i++) {
      if (edges[i].via && edges[i].via.length) { via = edges[i].via; break; }
    }
    via.forEach(v => {
      if (v && v.nx != null && v.ny != null) out.push([v.nx * IMG_W, v.ny * IMG_H]);
    });
    out.push([B.nx * IMG_W, B.ny * IMG_H]);
    return out;
  }

  // 沿法线偏移折线（拐点处用前后点的连线取法线，折角自然）
  function offPoly(pts, off) {
    if (!off || pts.length < 2) return pts;
    return pts.map((p, k) => {
      const a = pts[Math.max(0, k - 1)], b = pts[Math.min(pts.length - 1, k + 1)];
      const dx = b[0] - a[0], dy = b[1] - a[1], L = Math.hypot(dx, dy) || 1;
      return [p[0] + (-dy / L) * off, p[1] + (dx / L) * off];
    });
  }
  const ptsAttr = (pts, off) =>
    offPoly(pts, off).map(p => p[0].toFixed(2) + ',' + p[1].toFixed(2)).join(' ');

  // ════════════ 标记显隐（区域视图） ════════════
  // 只用 visibility，绝不能用 display:none ——
  // 坐标反解依赖标记父级的 left/top，display 会塌陷布局导致反解拿到空值。
  function applyNodeVisibility() {
    const host = S.overlayHost;
    if (!host || !S.byId) return 0;
    const hide = (S.view === 'region');   // 区域视图一律隐藏 L3+
    let hides = 0;
    let els = [];
    try { els = Array.prototype.slice.call(host.querySelectorAll('.openseadragon-overlay-wrapper')); }
    catch (e) { return 0; }
    els.forEach(el => {
      let lv = 0;
      try {
        const nm = (el.textContent || '').trim();
        const mid = markerIdOf(el);
        const id = (mid && S.placeByMarkerId && S.placeByMarkerId[mid]) || S.nameToId[norm(nm)];
        lv = (id && S.byId[id] && S.byId[id].level) || 0;
      } catch (e) { lv = 0; }
      if (hide && lv >= 3) {
        if (el.style.visibility !== 'hidden') el.style.visibility = 'hidden';
        if (el.style.pointerEvents !== 'none') el.style.pointerEvents = 'none';
        hides++;
      } else {
        if (el.style.visibility === 'hidden') el.style.visibility = '';
        if (el.style.pointerEvents === 'none') el.style.pointerEvents = '';
      }
    });
    S.hiddenCount = hides;
    return hides;
  }

  // ════════════ 图层 ════════════
  const NS = 'http://www.w3.org/2000/svg';

  function ensureLayer() {
    const doc = S.doc, canvas = S.canvas;
    if (!doc || !canvas) return false;
    const w = canvas.clientWidth || canvas.offsetWidth || 1;
    const h = canvas.clientHeight || canvas.offsetHeight || 1;
    if (S.svg && S.svg.parentElement === canvas) {
      if (+S.svg.getAttribute('width') !== w || +S.svg.getAttribute('height') !== h) {
        S.svg.setAttribute('width', w);
        S.svg.setAttribute('height', h);
        S.svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
        applyVeil();
      }
      // 标记层可能被 React 整个换掉过。此时 SVG 还在 canvas 里，但相对位置已失效，
      // 必须重新插回「当前标记层之前」，否则会跑到图标和地名上方。
      const host = S.overlayHost;
      if (host && host.parentElement === canvas) {
        if (S.svg.nextSibling !== host) canvas.insertBefore(S.svg, host);
      } else if (canvas.lastElementChild !== S.svg) {
        // 加载期还没有标记层：瓦片是后插进来的，保持在最上层才不会被图片盖住
        canvas.appendChild(S.svg);
      }
      return true;
    }
    const svg = doc.createElementNS(NS, 'svg');
    svg.setAttribute('id', '__geo_route_layer__');
    svg.setAttribute('width', w);
    svg.setAttribute('height', h);
    svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    // 不设 z-index：靠 DOM 顺序插入到标记层之前，即可稳稳待在标记之下。
    // 之前设了 z-index:1，反而越过了 z-index:auto 的标记层，把图标和地名盖住了。
    svg.style.cssText = 'position:absolute;left:0;top:0;overflow:visible;pointer-events:none';
    const host = S.overlayHost;
    if (host && host.parentElement === canvas) canvas.insertBefore(svg, host);
    else canvas.appendChild(svg);
    S.svg = svg;
    S.world = null;
    S.segs = [];
    S.currentMark = null;
    S.scaleApplied = false;

    // 压暗底图的蒙版：铺满画布的半透明黑矩形。
    // 它在路线之下、也在标记层之下，所以只会压暗地图本身。
    const veil = doc.createElementNS(NS, 'rect');
    veil.setAttribute('x', 0);
    veil.setAttribute('y', 0);
    veil.setAttribute('width', w);
    veil.setAttribute('height', h);
    veil.setAttribute('fill', '#06080c');
    veil.setAttribute('pointer-events', 'none');
    svg.appendChild(veil);
    S.veilEl = veil;
    applyVeil();                       // 关键：不调用则 opacity 默认为 1 → 整张地图全黑
    log('图层已插入 ' + w + 'x' + h + (host ? '（标记层之下）' : '（警告：置于最上）'));
    return true;
  }

  // 建线段元素（模式/数据变化时调用一次）
  // 几何全部用「图像坐标」（nx*IMG_W, ny*IMG_H）存放，
  // 整体缩放平移交给一个 <g> 的 transform，平移时只改 1 个属性 → 不卡。
  function buildSegments() {
    if (S.view === 'region') { buildRegionSegments(); return; }
    const doc = S.doc, svg = S.svg;
    if (!doc || !svg) return;
    if (S.world && S.world.parentElement) S.world.parentElement.removeChild(S.world);
    S.segs = [];
    S.currentMark = null;

    const world = doc.createElementNS(NS, 'g');
    world.setAttribute('id', '__geo_world__');
    svg.appendChild(world);
    S.world = world;

    const pairs = visiblePairs();

    pairs.forEach(pr => {
      const A = S.placeCoord[pr.a], B = S.placeCoord[pr.b];
      if (!A || !B) return;
      const edges = S.geo.edges.filter(e =>
        (e.from === pr.a && e.to === pr.b) || (e.from === pr.b && e.to === pr.a));
      if (!edges.length) return;

      const visibleEdges = edges.filter(e =>
        (e.segments || []).some(s => !S.transportOff.has(s.transport)));
      if (!visibleEdges.length) return;

      const pts = buildPts(A, B, visibleEdges);

      const halo = doc.createElementNS(NS, 'polyline');
      halo.setAttribute('fill', 'none');
      halo.setAttribute('stroke', '#04070b');
      halo.setAttribute('stroke-linecap', 'round');
      halo.setAttribute('stroke-linejoin', 'round');
      halo.setAttribute('opacity', '0.8');
      world.appendChild(halo);

      // 一条边可能含多种交通方式（船只 / 徒步 …）：
      // 每种方式各画一根并排线，而不是只画最快那一种。
      const items = [];
      visibleEdges.forEach(e => {
        const byTp = {};
        (e.segments || []).forEach(sg => {
          if (S.transportOff.has(sg.transport)) return;
          const key = sg.transport || '';
          const cur = byTp[key];
          if (!cur || (sg.days != null && (cur.days == null || sg.days < cur.days))) byTp[key] = sg;
        });
        Object.keys(byTp).forEach(key => {
          const sg = byTp[key];
          // 每条线自带黑底：虚线时黑底也断开，缝隙露出的是地图而不是黑条
          const h2 = doc.createElementNS(NS, 'polyline');
          h2.setAttribute('fill', 'none');
          h2.setAttribute('stroke', '#04070b');
          h2.setAttribute('stroke-linecap', 'round');
          h2.setAttribute('stroke-linejoin', 'round');
          h2.setAttribute('opacity', '0.85');
          world.appendChild(h2);
          const line = doc.createElementNS(NS, 'polyline');
          line.setAttribute('fill', 'none');
          line.setAttribute('stroke', tColor(sg.transport));
          line.setAttribute('stroke-linecap', 'round');
          line.setAttribute('stroke-linejoin', 'round');
          line.setAttribute('stroke-dasharray', dashOf(sg.transport));
          line.setAttribute('opacity', '0.8');
          world.appendChild(line);
          items.push({ el: line, halo2: h2, edge: e, best: sg });
        });
      });
      if (!items.length) return;

      S.segs.push({
        a: pr.a, b: pr.b,
        au: A.nx * IMG_W, av: A.ny * IMG_H,
        bu: B.nx * IMG_W, bv: B.ny * IMG_H,
        pts: pts,
        halo, items
      });
    });

    S.built = true;
    S.scaleApplied = false;
    applyScaleDependent();
    applyWorld();
    S.lastBuild = Date.now();
    applyNodeVisibility();   // 节点视图：把状态恢复成「全部可见」
    log('已建线段 ' + S.segs.length + ' 组 / ' + S.segs.reduce((n, g) => n + g.items.length, 0) + ' 根（模式 ' + S.mode + '）');
    renderPanel();
  }

  // ── 区域视图：把点间路线按 topScope 区块聚合成一根线 ──
  function buildRegionSegments() {
    const doc = S.doc, svg = S.svg;
    if (!doc || !svg) return;
    if (S.world && S.world.parentElement) S.world.parentElement.removeChild(S.world);
    S.segs = [];
    S.currentMark = null;

    const world = doc.createElementNS(NS, 'g');
    world.setAttribute('id', '__geo_world__');
    svg.appendChild(world);
    S.world = world;

    // 聚合
    const map = {};
    S.geo.edges.forEach(e => {
      const ba = blockOf(e.from), bb = blockOf(e.to);
      if (!ba || !bb || ba === bb) return;
      if (ba === 'continent' || bb === 'continent') return;  // 大陆本身不参与区块
      if (!S.byId[ba] || !S.byId[bb]) return;
      const key = ba < bb ? (ba + '|' + bb) : (bb + '|' + ba);
      if (!map[key]) map[key] = { a: ba, b: bb, edges: [] };
      map[key].edges.push(e);
    });

    Object.keys(map).forEach(key => {
      const ag = map[key];
      const A = blockCoord(ag.a), B = blockCoord(ag.b);
      if (!A || !B) return;

      // 选出最快的一段做样式（颜色/线型/线宽）；天数缺失时退回第一条可见段
      let bestSeg = null, fallbackSeg = null;
      ag.edges.forEach(e => (e.segments || []).forEach(sg => {
        if (S.transportOff.has(sg.transport)) return;
        if (!fallbackSeg) fallbackSeg = sg;
        if (sg.days == null) return;
        if (!bestSeg || sg.days < bestSeg.days) bestSeg = sg;
      }));
      if (!bestSeg) bestSeg = fallbackSeg;
      if (!bestSeg) return;

      // 合成清单：去重后的 a→b
      const seenTxt = {}, comp = [];
      ag.edges.forEach(e => {
        const an = S.byId[e.from], bn = S.byId[e.to];
        if (!an || !bn) return;
        const t = an.name + '→' + bn.name;
        if (seenTxt[t]) return;
        seenTxt[t] = 1;
        comp.push(t);
      });

      const halo = doc.createElementNS(NS, 'polyline');
      halo.setAttribute('fill', 'none');
      halo.setAttribute('stroke', '#04070b');
      halo.setAttribute('stroke-linecap', 'round');
      halo.setAttribute('stroke-linejoin', 'round');
      halo.setAttribute('opacity', '0.8');
      world.appendChild(halo);

      const h2 = doc.createElementNS(NS, 'polyline');
      h2.setAttribute('fill', 'none');
      h2.setAttribute('stroke', '#04070b');
      h2.setAttribute('stroke-linecap', 'round');
      h2.setAttribute('stroke-linejoin', 'round');
      h2.setAttribute('opacity', '0.85');
      world.appendChild(h2);

      const line = doc.createElementNS(NS, 'polyline');
      line.setAttribute('fill', 'none');
      line.setAttribute('stroke', tColor(bestSeg.transport));
      line.setAttribute('stroke-linecap', 'round');
      line.setAttribute('stroke-linejoin', 'round');
      line.setAttribute('opacity', '0.8');
      world.appendChild(line);

      S.segs.push({
        a: ag.a, b: ag.b,
        au: A.nx * IMG_W, av: A.ny * IMG_H,
        bu: B.nx * IMG_W, bv: B.ny * IMG_H,
        pts: [[A.nx * IMG_W, A.ny * IMG_H], [B.nx * IMG_W, B.ny * IMG_H]],
        halo: halo,
        items: [{ el: line, halo2: h2, best: bestSeg, edge: ag.edges[0] }],
        agg: comp
      });
    });

    S.built = true;
    S.scaleApplied = false;
    applyScaleDependent();
    applyWorld();
    S.lastBuild = Date.now();
    const hd = applyNodeVisibility();
    log('已建区域线 ' + S.segs.length + ' 根（区域视图）' + (hd ? '，隐藏节点标记 ' + hd + ' 个' : ''));
    renderPanel();
  }

  // 随缩放变化的量：线宽 / 并排偏移 / 描边 / 当前圈半径（只在 k 变化时跑）
  function applyScaleDependent() {
    if (!S.world) return;
    const k = S.k || 1;
    const gapImg = GAP_PX / k;
    const baseImg = LINE_W / k;
    const haloImg = HALO_PX / k;

    S.segs.forEach(seg => {
      const n = seg.items.length;
      // 每条线自己的宽度（屏幕像素 → 图像单位）
      const ws = seg.items.map(it => wOf(it.best ? it.best.transport : '') / k);
      const totalImg = ws.reduce((a, b) => a + b, 0) + gapImg * Math.max(0, n - 1);
      const dx = seg.bu - seg.au, dy = seg.bv - seg.av;
      const len = Math.hypot(dx, dy) || 1;
      const nx = -dy / len, ny = dx / len;

      // 一束里只要有一条虚线，整束就不能铺实心黑底（虚线缝隙会露出黑条）
      const anyDash = seg.items.some(it => dashOf(it.best ? it.best.transport : ''));
      const pts = seg.pts || [[seg.au, seg.av], [seg.bu, seg.bv]];
      seg.halo.setAttribute('points', ptsAttr(pts, 0));
      seg.halo.setAttribute('stroke-width', anyDash ? 0 : (totalImg + 2 * haloImg));

      let cur = -totalImg / 2;
      seg.items.forEach((it, wi) => {
        const wImg = ws[wi] != null ? ws[wi] : baseImg;
        const off = cur + wImg / 2;
        cur += wImg + gapImg;
        it.el.setAttribute('points', ptsAttr(pts, off));
        it.el.setAttribute('stroke-width', wImg);
        // 虚线间距按 k 换算，屏幕上尺寸恒定
        const rawDash = dashOf(it.best ? it.best.transport : '');
        const dashStr = rawDash
          ? rawDash.split(/[\s,]+/).map(v => (parseFloat(v) || 0) / k).join(' ')
          : '';
        it.el.setAttribute('stroke-dasharray', dashStr);
        // 逐条黑底：同位置、同虚线、略宽
        if (it.halo2) {
          it.halo2.setAttribute('points', ptsAttr(pts, off));
          it.halo2.setAttribute('stroke-dasharray', dashStr);
          it.halo2.setAttribute('stroke-width', anyDash ? (wImg + 2 * haloImg) : 0);
        }
      });
    });

    updateHere();
    S.scaleApplied = true;
  }

  // 动画关键帧（注入到地图所在的 document，只注入一次）
  function ensureStyle() {
    const doc = S.doc;
    if (!doc || doc.getElementById('__geo_route_style__')) return;
    const st = doc.createElement('style');
    st.id = '__geo_route_style__';
    st.textContent =
      // 两个动画都只动 transform —— 合成器即可处理，不触发重绘。
      // 不要在这里加 filter：滤镜动画无法上合成器，手机上会明显掉帧。
      //
      // 上下浮动（只做位移）
      '@keyframes __geoBob{' +
      '0%,100%{transform:translateY(0)}' +
      '50%{transform:translateY(-9px)}' +
      '}' +
      // 绕竖直轴(Y)来回摆：尖端始终朝下。
      // 摆到 ±90° 时三角面正好侧对屏幕（零宽），此时由垂直的侧棱顶上。
      '@keyframes __geoFlip{' +
      '0%,100%{transform:rotateY(-90deg)}' +
      '50%{transform:rotateY(90deg)}' +
      '}';
    (doc.head || doc.documentElement).appendChild(st);
  }

  // ── 所在地标记（DOM 层，浮在地图标签之上）──
  function ensureHereMarker() {
    const doc = S.doc, canvas = S.canvas;
    if (!doc || !canvas) return;
    if (S.hereEl && S.hereEl.parentElement === canvas) return;
    if (S.hereEl && S.hereEl.parentElement) S.hereEl.parentElement.removeChild(S.hereEl);
    ensureStyle();
    const box = doc.createElement('div');
    box.id = '__geo_here__';
    // 外层负责定位（把三角形的尖端对准坐标点），内层负责动画
    box.style.cssText = 'position:absolute;left:0;top:0;pointer-events:none;' +
      'transform:translate(-50%,-100%);z-index:2;display:none';
    // 系统开启「减少动态效果」时完全静止
    const Win = doc.defaultView;
    const noAnim = !!(Win && Win.matchMedia &&
      Win.matchMedia('(prefers-reduced-motion: reduce)').matches);
    const aBob = noAnim ? '' : 'animation:__geoBob 2.2s ease-in-out infinite;';
    const aFlip = noAnim ? '' : 'animation:__geoFlip 2.6s ease-in-out infinite;';

    box.innerHTML =
      '<div style="' + aBob + 'perspective:180px;will-change:transform">' +
        '<div style="' + aFlip + 'position:relative;width:20px;height:18px;' +
        'transform-origin:50% 50%;transform-style:preserve-3d;' +
        'backface-visibility:visible;will-change:transform">' +
          // 阴影：略大的深色三角，纯几何，不用 blur 滤镜
          '<div style="position:absolute;left:-1px;top:1px;width:0;height:0;' +
          'border-left:11px solid transparent;border-right:11px solid transparent;' +
          'border-top:19px solid rgba(0,0,0,.5)"></div>' +
          // 主面：白色三角
          '<div style="position:absolute;left:0;top:0;width:0;height:0;' +
          'border-left:10px solid transparent;border-right:10px solid transparent;' +
          'border-top:18px solid #ffffff"></div>' +
          // 摆到 ±90° 时三角面收成零宽、短暂消失再转回来 —— 这就是要的效果。
        '</div>' +
      '</div>';
    canvas.appendChild(box);           // 追加在标记层之后 → 盖在地图标签之上
    S.hereEl = box;
    updateHere();
  }

  function updateHere() {
    if (!S.hereEl) return;
    if (!S.show || !S.currentId || !S.placeCoord[S.currentId]) {
      S.hereEl.style.display = 'none';
      return;
    }
    const c = S.placeCoord[S.currentId];
    // 用纯换算，不走路线锚点 —— 两条偏移互不影响
    const [x, y] = imgToRawPx(c.nx * IMG_W, c.ny * IMG_H);
    S.hereEl.style.display = 'block';
    S.hereEl.style.left = (x + HERE_NUDGE.x) + 'px';
    S.hereEl.style.top = (y + HERE_NUDGE.y) + 'px';
  }

  function applyVeil() {
    if (!S.veilEl) return;
    const canvas = S.canvas;
    const w = (canvas && (canvas.clientWidth || canvas.offsetWidth)) || 1;
    const h = (canvas && (canvas.clientHeight || canvas.offsetHeight)) || 1;
    S.veilEl.setAttribute('width', w);
    S.veilEl.setAttribute('height', h);
    S.veilEl.setAttribute('opacity', String(S.veil / 100));
  }

  // 只改整组变换（平移时每帧就这一条，开销极小）
  function applyWorld() {
    if (!S.world) return;
    S.world.setAttribute('transform',
      'translate(' + (S.ox + S.anchor.x + S.nudge.x) + ' ' +
                     (S.oy + S.anchor.y + S.nudge.y) + ') scale(' + S.k + ')');
    updateHere();
  }

  // ════════════ 面板 ════════════
  function ensurePanel() {
    const doc = S.doc;
    const anchor = S.canvas && S.canvas.parentElement;
    if (!doc || !anchor) return;
    if (S.panel && S.panel.parentElement === anchor) return;
    const p = doc.createElement('div');
    p.id = '__geo_route_panel__';
    p.style.cssText = [
      'position:absolute', PANEL_POS === 'br' ? 'right:10px' : 'left:10px', 'bottom:10px', 'z-index:9000',
      'background:rgba(16,20,27,.95)', 'border:1px solid #33414f', 'border-radius:8px',
      'padding:7px 9px', 'font:11px/1.7 "Microsoft YaHei",sans-serif', 'color:#d6dde6',
      'box-shadow:0 6px 22px rgba(0,0,0,.55)', 'pointer-events:auto', 'user-select:none',
      'max-width:260px'
    ].join(';');
    anchor.appendChild(p);
    S.panel = p;
    // 面板位于 OpenSeadragon 容器内部，若不拦截，拖滑杆会被 OSD 当成拖地图抢走
    ['pointerdown', 'mousedown', 'touchstart', 'wheel', 'dblclick', 'contextmenu']
      .forEach(t => p.addEventListener(t, (e) => e.stopPropagation(), { capture: true }));

    const tip = doc.createElement('div');
    tip.id = '__geo_route_tip__';
    tip.style.cssText = [
      'position:absolute', 'z-index:9001', 'pointer-events:none', 'display:none',
      'background:rgba(10,14,20,.96)', 'border:1px solid #3f4d5d', 'border-radius:6px',
      'padding:5px 8px', 'font:11px/1.65 "Microsoft YaHei",sans-serif', 'color:#e6edf5',
      'max-width:240px', 'box-shadow:0 4px 14px rgba(0,0,0,.6)'
    ].join(';');
    anchor.appendChild(tip);
    S.tip = tip;

    renderPanel();
    bindCanvasEvents();
  }

  function btn(label, on, data) {
    return '<button data-act="' + data + '" style="background:' +
      (on ? '#1d4ed8' : '#222c39') + ';border:1px solid ' + (on ? '#3b82f6' : '#33414f') +
      ';color:' + (on ? '#fff' : '#c3ced9') + ';padding:2px 7px;border-radius:5px;' +
      'cursor:pointer;font-size:11px;margin:1px 2px 1px 0">' + label + '</button>';
  }

  const MINI_BTN = 'background:#222c39;border:1px solid #33414f;color:#c3ced9;' +
    'padding:0 5px;border-radius:4px;cursor:pointer;font-size:10.5px;line-height:16px';

  function panelEdge(p) {
    if (PANEL_POS === 'br') { p.style.right = '10px'; p.style.left = 'auto'; }
    else { p.style.left = '10px'; p.style.right = 'auto'; }
  }

  function renderPanel(msg) {
    const p = S.panel;
    if (!p) return;

    // ── 折叠态：细长竖条 ──
    if (!S.ui.open) {
      panelEdge(p);
      p.style.bottom = '10px';
      p.style.top = 'auto';
      p.style.transform = 'none';
      p.style.width = '26px';
      p.style.padding = '6px 4px';
      p.innerHTML =
        '<div style="display:flex;flex-direction:column;align-items:center;gap:7px">' +
        '<button data-act="ui" title="展开" style="' + MINI_BTN + 'width:20px;height:20px;' +
        'line-height:16px;font-size:13px;padding:0">+</button>' +
        '<div style="writing-mode:vertical-rl;text-orientation:upright;letter-spacing:3px;' +
        'color:#22d3ee;font-size:11px;user-select:none">地理路线</div>' +
        '</div>';
      bindPanel(p);
      return;
    }

    // ── 展开态 ──
    panelEdge(p);
    p.style.bottom = '10px';
    p.style.top = 'auto';
    p.style.transform = 'none';
    p.style.width = 'auto';
    p.style.padding = '7px 9px';

    // 标题行：地理路线 map-r12 ｜ 162组/楼层37 ｜ 收起
    const floorTxt = (S.panelInfo && S.panelInfo.msgId != null) ? String(S.panelInfo.msgId) : '—';
    const missN = S.coordStat ? (S.coordStat.miss || []).length : 0;
    let h = '<div style="display:flex;align-items:baseline;gap:6px;min-width:150px">' +
      '<span style="font-weight:700;color:#22d3ee;white-space:nowrap">地理路线 ' + VERSION + '</span>' +
      '<span style="color:#64748b;font-size:10.5px;white-space:nowrap">' +
        S.segs.length + '组/楼层' + floorTxt +
        (missN ? ' · <span style="color:#eab308">缺' + missN + '</span>' : '') +
      '</span>' +
      '<span style="flex:1"></span>' +
      '<button data-act="ui" title="收起" style="' + MINI_BTN + '">−</button></div>';

    // 1跳/2跳/全图 = 单选框（方形填充）
    // 节点/区域 = 开关（胶囊滑块），造型和配色都不同
    // 区域：单键开关。亮 = 区域视图，暗 = 节点视图
    const onRegion = S.view === 'region';
    const vBtn = '<button data-act="vswitch" title="' +
      (onRegion ? '当前：区域视图（点击回到节点视图）' : '当前：节点视图（点击切到区域视图）') +
      '" style="background:' + (onRegion ? '#0e7490' : '#222c39') +
      ';border:1px solid ' + (onRegion ? '#22d3ee' : '#33414f') +
      ';color:' + (onRegion ? '#fff' : '#8b98a8') +
      ';font-weight:' + (onRegion ? '700' : '400') +
      ';padding:2px 10px;border-radius:999px;cursor:pointer;font-size:11px;' +
      'line-height:1.6;font-family:inherit;margin-left:4px">区域</button>';

    h += '<div style="margin:4px 0;display:flex;align-items:center;gap:3px;flex-wrap:wrap">' +
      btn('显示', S.show, 'toggle') +
      btn('1跳', S.mode === 'hop1', 'm1') +
      btn('2跳', S.mode === 'hop2', 'm2') +
      btn('全图', S.mode === 'all', 'mall') +
      vBtn + '</div>';

    const cur = S.currentId ? S.byId[S.currentId] : null;
    const rawLoc = (S.panelInfo && S.panelInfo.loc) || '';
    h += '<div style="color:#8b98a8" title="' + esc(rawLoc) + '">当前位置：<b style="color:#eef4fb;font-weight:700">' +
      (cur ? esc(cur.name) : '<span style="color:#eab308">未识别</span>') + '</b>' +
      (cur ? '' : '<span style="color:#64748b;font-size:10.5px"> ' + esc(rawLoc.slice(0, 18)) + '</span>') +
      '</div>';

    if (S.currentId && S.segs.length === 0 && (S.mode === 'hop1' || S.mode === 'hop2')) {
      h += '<div style="color:#eab308">当前位置没有路线记录，试试切到「全图」</div>';
    }
    if (msg) h += '<div style="color:#eab308">' + msg + '</div>';

    // 底图压暗
    h += '<div style="margin-top:5px;border-top:1px solid #26313d;padding-top:4px">' +
      '<div style="display:flex;align-items:center;gap:6px;color:#8b98a8">' +
      '<span>底图压暗</span>' +
      '<input data-act="veil" type="range" min="0" max="90" step="5" value="' + S.veil +
      '" style="flex:1;height:14px;accent-color:#22d3ee;cursor:pointer">' +
      '<span id="__geo_veil_label__" style="width:34px;text-align:right">' + S.veil + '%</span>' +
      '</div></div>';

    // 交通方式（可折叠）
    if (S.geo) {
      const ts = {};
      S.geo.edges.forEach(e => (e.segments || []).forEach(x => {
        const t = x.transport || '?';
        ts[t] = (ts[t] || 0) + 1;
      }));
      const keys = Object.keys(ts).sort((a, b) => ts[b] - ts[a]);
      const onCount = keys.filter(t => !S.transportOff.has(t)).length;
      h += '<div style="margin-top:5px;border-top:1px solid #26313d;padding-top:4px">';
      h += '<div data-act="tcollapse" title="点此展开 / 收起" style="display:flex;' +
        'align-items:center;gap:7px;background:#222c39;border:1px solid #3a4655;' +
        'border-radius:5px;padding:4px 8px;color:#c3ced9;cursor:pointer;' +
        'user-select:none;font-size:11.5px">' +
        '<span style="font-size:26px;line-height:0.9;color:#7dd3fc">' +
        (S.ui.transportOpen ? '▾' : '▸') + '</span>' +
        '<span>交通方式</span>' +
        '<span style="flex:1"></span>' +
        '<span style="color:#7f8ea3">' + onCount + '/' + keys.length + '</span></div>';
      if (S.ui.transportOpen) {
        h += '<div style="margin-top:3px">';
        keys.forEach(t => {
          const on = !S.transportOff.has(t);
          h += '<button data-act="t:' + t + '" style="background:' + (on ? '#222c39' : '#141a22') +
            ';border:1px solid ' + (on ? '#3a4655' : '#1d2530') + ';color:' +
            (on ? tColor(t) : '#4b5563') +
            ';padding:1px 5px;border-radius:4px;cursor:pointer;font-size:10.5px;margin:1px 2px 1px 0">' +
            t + ' ' + ts[t] + '</button>';
        });
        h += '</div>';
      }
      h += '</div>';
    }

    p.innerHTML = h;
    bindPanel(p);
  }

  function bindPanel(p) {
    p.querySelectorAll('[data-act]').forEach(el => {
      if (el.tagName === 'INPUT') return;      // 滑杆只走 oninput，不能被点击重渲染打断
      el.onclick = (ev) => {
        ev.stopPropagation();
        onAct(el.getAttribute('data-act'));
      };
    });
    const rng = p.querySelector('input[data-act="veil"]');
    if (rng) {
      rng.oninput = (ev) => {
        ev.stopPropagation();
        S.veil = +ev.target.value;
        applyVeil();
        const lab = p.querySelector('#__geo_veil_label__');
        if (lab) lab.textContent = S.veil + '%';
      };
      rng.onchange = () => savePrefs();
      rng.onmousedown = (ev) => ev.stopPropagation();
    }
  }

  function onAct(a) {
    if (a === 'ui') {
      S.ui.open = !S.ui.open;
      savePrefs();
    } else if (a === 'toggle') {
      S.show = !S.show; applyShow();
    } else if (a === 'm1' || a === 'm2' || a === 'mall') {
      S.mode = a === 'm1' ? 'hop1' : a === 'm2' ? 'hop2' : 'all';
      savePrefs();
      buildSegments();
      return;
    } else if (a === 'vswitch' || a === 'vn' || a === 'vr') {
      S.view = (a === 'vn') ? 'node' : (a === 'vr' ? 'region'
               : (S.view === 'node' ? 'region' : 'node'));
      S.blockCoord = {};
      savePrefs();
      buildSegments();
      return;
    } else if (a === 'tcollapse') {
      S.ui.transportOpen = !S.ui.transportOpen;
      savePrefs();
    } else if (a.indexOf('t:') === 0) {
      const t = a.slice(2);
      if (S.transportOff.has(t)) S.transportOff.delete(t); else S.transportOff.add(t);
      savePrefs();
      buildSegments();
      return;
    }
    renderPanel();
  }

  function applyShow() {
    if (S.svg) S.svg.style.display = S.show ? '' : 'none';
    updateHere();
  }

  function savePrefs() {
    try {
      localStorage.setItem('__geo_route_prefs__',
        JSON.stringify({ veil: S.veil, open: S.ui.open, transportOpen: S.ui.transportOpen,
                         view: S.view, mode: S.mode, hideNodes: S.hideNodes,
                         transportOff: Array.from(S.transportOff) }));
    } catch (e) {}
  }
  function loadPrefs() {
    try {
      const v = localStorage.getItem('__geo_route_prefs__');
      if (!v) return;
      const o = JSON.parse(v);
      if (!o) return;
      if (isFinite(o.veil)) S.veil = Math.max(0, Math.min(90, o.veil));
      if (typeof o.open === 'boolean') S.ui.open = o.open;
      if (typeof o.transportOpen === 'boolean') S.ui.transportOpen = o.transportOpen;
      if (o.view === 'node' || o.view === 'region') S.view = o.view;
      if (o.mode === 'hop1' || o.mode === 'hop2' || o.mode === 'all') S.mode = o.mode;
      if (Array.isArray(o.transportOff)) S.transportOff = new Set(o.transportOff.map(String));
    } catch (e) {}
  }
  // ════════════ 悬停提示 ════════════
  function bindCanvasEvents() {
    if (!S.canvas || S.canvas._geoBound) return;
    S.canvas._geoBound = true;
    const Win = S.doc.defaultView;
    S.canvas.addEventListener('mousemove', (ev) => {
      // 切换目标地图后，旧画布上的监听器仍然存在。
      // 若不拦住，它会把「旧地图的鼠标位置」配「新地图的坐标系」算，提示框会错位。
      if (!S.canvas || ev.currentTarget !== S.canvas) return;
      if (!S.show || !S.segs.length || !S.tip) { hideTip(); return; }
      const rect = S.canvas.getBoundingClientRect();
      const mx = ev.clientX - rect.left, my = ev.clientY - rect.top;
      let best = null, bestD = HIT_PX;
      S.segs.forEach(seg => {
        const ps = seg.pts || [[seg.au, seg.av], [seg.bu, seg.bv]];
        for (let i = 0; i + 1 < ps.length; i++) {
          const p1 = imgToCanvasPx(ps[i][0], ps[i][1]);
          const p2 = imgToCanvasPx(ps[i + 1][0], ps[i + 1][1]);
          const d = distToSeg(mx, my, p1[0], p1[1], p2[0], p2[1]);
          if (d < bestD) { bestD = d; best = seg; }
        }
      });
      if (!best) { hideTip(); return; }
      showTip(ev, best);
    }, { passive: true });
    S.canvas.addEventListener('mouseleave', (ev) => {
      if (!S.canvas || ev.currentTarget !== S.canvas) return;
      hideTip();
    }, { passive: true });
  }

  function distToSeg(px, py, x1, y1, x2, y2) {
    const dx = x2 - x1, dy = y2 - y1;
    const l2 = dx * dx + dy * dy;
    if (!l2) return Math.hypot(px - x1, py - y1);
    let t = ((px - x1) * dx + (py - y1) * dy) / l2;
    t = Math.max(0, Math.min(1, t));
    return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));
  }

  function showTip(ev, seg) {
    const tip = S.tip;
    if (!tip) return;

    // 区域视图：只报合成清单
    if (seg.agg) {
      let h = '<div style="color:#8b98a8;margin-bottom:2px">该线由以下路线合成：</div>';
      h += seg.agg.map(x => '<div style="color:#c9d6e3">' + x + '</div>').join('');
      tip.innerHTML = h;
      tip.style.display = 'block';
      const anc = S.canvas.parentElement;
      const ar = anc.getBoundingClientRect();
      let x = ev.clientX - ar.left + 14;
      let y = ev.clientY - ar.top + 14;
      const tw = tip.offsetWidth, th = tip.offsetHeight;
      if (x + tw > ar.width - 6) x = ev.clientX - ar.left - tw - 14;
      if (y + th > ar.height - 6) y = ev.clientY - ar.top - th - 14;
      tip.style.left = Math.max(4, x) + 'px';
      tip.style.top = Math.max(4, y) + 'px';
      return;
    }
    const A = S.byId[seg.a], B = S.byId[seg.b];
    if (!A || !B) { hideTip(); return; }
    let h = '<div style="font-weight:700;margin-bottom:2px">' + A.name + ' ↔ ' + B.name + '</div>';
    seg.items.forEach(it => {
      const s = it.best;
      if (!s) return;
      const parts = [];
      parts.push('<b style="color:' + tColor(s.transport) + '">' + (s.transport || '?') + '</b>');
      if (s.days != null) parts.push(s.days + ' 天');
      if (s.terrain && s.terrain.length) parts.push(s.terrain.join('/'));
      if (s.direction) parts.push(s.direction);
      h += '<div>' + parts.join(' · ') + '</div>';
    });
    tip.innerHTML = h;
    tip.style.display = 'block';
    const anchor = S.canvas.parentElement;
    const ar = anchor.getBoundingClientRect();
    let x = ev.clientX - ar.left + 14;
    let y = ev.clientY - ar.top + 14;
    const tw = tip.offsetWidth, th = tip.offsetHeight;
    if (x + tw > ar.width - 6) x = ev.clientX - ar.left - tw - 14;
    if (y + th > ar.height - 6) y = ev.clientY - ar.top - th - 14;
    tip.style.left = Math.max(4, x) + 'px';
    tip.style.top = Math.max(4, y) + 'px';
  }

  function hideTip() {
    if (S.tip) S.tip.style.display = 'none';
  }

  // ════════════ 主循环 ════════════
  // 同步更新：在 OSD 改动标记位置的同一个任务里就把整组变换写好，
  // 不再等 requestAnimationFrame，否则会始终晚一帧 → 拖动时明显滞后。
  function syncNow() {
    try {
      if (!S.svg || !S.world) return;
      const rs = collectRefs();
      if (rs.length < 2) return;
      const oldK = S.k;
      if (!solveTransform(rs)) return;
      S.ready = true;
      if (!S.scaleApplied || Math.abs(S.k - oldK) > 1e-9) applyScaleDependent();
      applyWorld();
    } catch (e) { warn('同步失败', e); }
  }

  let observer = null, visObserver = null, visTimer = null;
  function attachObserver() {
    if (observer) { try { observer.disconnect(); } catch (e) {} observer = null; }
    const host = S.overlayHost, Win = S.doc && S.doc.defaultView;
    if (!host || !Win) return;
    observer = new Win.MutationObserver(() => syncNow());
    S.refEls.forEach(r => {
      try { observer.observe(r.el, { attributes: true, attributeFilter: ['style'] }); } catch (e) {}
    });
    try { observer.observe(host, { childList: true }); } catch (e) {}

    // OSD 重建标记会冲掉我们加的 style，单独再挂一个观察者重新应用
    if (visObserver) { try { visObserver.disconnect(); } catch (e) {} visObserver = null; }
    try {
      visObserver = new Win.MutationObserver(() => {
        if (visTimer) return;
        visTimer = setTimeout(() => { visTimer = null; applyNodeVisibility(); }, 60);
      });
      visObserver.observe(host, { childList: true });
    } catch (e) {}
  }

  function geoChanged() {
    // 数据版本或当前位置变化时重建
    const g = S.geo ? String(S.geo.version) : '';
    const cur = readCurrent();
    if (g !== S.lastGeo || cur !== S.currentId) {
      S.lastGeo = g;
      S.currentId = cur;
      return true;
    }
    return false;
  }

  // 定期刷新三样东西：楼层位置 / 地理数据版本 / 标记位置指纹
  function refreshStat() {
    // ① 这张地图所属楼层的位置（楼层变量，不是聊天变量）
    try {
      const win = S.doc && S.doc.defaultView;
      if (win) {
        const st = panelState(win);
        if (st.msgId !== S.panelInfo.msgId || st.loc !== S.panelInfo.loc) {
          const msgChanged = st.msgId !== S.panelInfo.msgId;
          log('楼层 ' + (st.msgId == null ? '?' : st.msgId) + ' 地点：' + (st.loc || '（空）'));
          S.panelInfo = st;
          // 面板标题里带楼层号，换层了要重画标题
          if (msgChanged && S.panel) renderPanel();
        }
      }
    } catch (e) {}

    // ② 地理数据换了（compact ↔ poem，或版本变了）→ 重建
    //    这块数据很大、又极少变，每 4 次刷新（约 20 秒）查一次就够。
    try {
      if ((S.geoPoll = (S.geoPoll || 0) + 1) % 4 === 1) {
        const src = readGeoSource();
        const key = src
          ? (src.kind + ':' + String(src.kind === 'compact' ? (src.raw.version || '') : (src.raw.v || '')))
          : 'none';
        if (key !== S.geoSourceKey) {
          if (S.geoSourceKey) {
            log('地理数据变化（' + S.geoSourceKey + ' → ' + key + '），准备重建');
            S.geo = null; S.anchorDone = false; S.refEls = []; S.built = false;
          }
          S.geoSourceKey = key;
        }
      }
    } catch (e) {}

    // ③ 玩家拖动 / 改名 / 增删标记 → 坐标变了，重建
    try {
      const chr = getVariables({ type: 'character' });
      const mk = chr && chr.map_markers;
      if (Array.isArray(mk)) {
        const sig = markerSignature(mk);
        if (S.markerSig && sig !== S.markerSig) {
          log('地图标记有变动，准备重建');
          S.geo = null; S.anchorDone = false; S.refEls = []; S.built = false;
        }
      }
    } catch (e) {}
  }

  // 把「挂在某张地图上」的所有自有节点摘掉。
  // 切换目标地图时必须调用，否则旧地图会留下一份快照：
  // 滚动回去就会和新画的叠在一起（三角和线段各一份，最多叠到三层）。
  function unmountFrom(canvas) {
    if (!canvas) return;
    try {
      canvas.querySelectorAll('.openseadragon-overlay-wrapper').forEach(el => {
        if (el.style.visibility === 'hidden') el.style.visibility = '';
        if (el.style.pointerEvents === 'none') el.style.pointerEvents = '';
      });
    } catch (e) {}
    try {
      canvas.querySelectorAll('#__geo_route_layer__, #__geo_here__')
        .forEach(function (n) { try { n.remove(); } catch (e) {} });
    } catch (e) {}
    try {
      const par = canvas.parentElement;
      if (par) {
        par.querySelectorAll('#__geo_route_panel__, #__geo_route_tip__')
          .forEach(function (n) { try { n.remove(); } catch (e) {} });
      }
    } catch (e) {}
  }

  // 兜底清扫：热替换脚本时，旧实例可能已经在别的文档里留下图层。
  // 只清「不是当前正在用的那几个」，避免误删自己。
  function sweepStale() {
    const keep = [S.svg, S.panel, S.tip, S.hereEl].filter(Boolean);
    const mine = ['__geo_route_layer__', '__geo_here__', '__geo_route_panel__', '__geo_route_tip__'];
    let n = 0;
    const seen = new Set();
    const wins = [window];
    try { if (window.top && window.top !== window) wins.push(window.top); } catch (e) {}
    for (let i = 0; i < wins.length; i++) {
      let fr = null;
      try { fr = wins[i].frames; } catch (e) { continue; }
      if (!fr) continue;
      for (let k = 0; k < fr.length && k < 40; k++) {
        try { if (wins.indexOf(fr[k]) < 0) wins.push(fr[k]); } catch (e) {}
      }
    }
    wins.forEach(function (w) {
      let d = null; try { d = w.document; } catch (e) { return; }
      if (!d || seen.has(d)) return;
      seen.add(d);
      mine.forEach(function (id) {
        try {
          d.querySelectorAll('#' + id).forEach(function (el) {
            if (keep.indexOf(el) >= 0) return;
            try { el.remove(); n++; } catch (e) {}
          });
        } catch (e) {}
      });
    });
    if (n) log('清扫遗留图层 ' + n + ' 个');
  }

  // 地图容器被卸载（切标签页）时，把与这个地图绑定的一切清掉，等它重建
  function resetMap() {
    if (observer) { try { observer.disconnect(); } catch (e) {} observer = null; }
    unmountFrom(S.canvas);
    S.doc = null; S.container = null; S.canvas = null; S.overlayHost = null;
    S.svg = null; S.world = null; S.panel = null; S.tip = null;
    S.segs = []; S.currentMark = null;
    S.refEls = []; S.ready = false; S.scaleApplied = false; S.lastBuild = 0;
    S.built = false; S.hereEl = null;
    S.panelInfo = { msgId: null, loc: '' };
    log('地图已卸载，等待重新挂载');
  }

  function tick() {
    try {
      S.tickN++;
      if (S.tickN % 6 === 0) refreshStat();       // 约每 5 秒刷新一次 stat_data
      if (!S.geo) buildModel();

      // ① 失效检测：画布 / 标记层 / 图层 任一脱离文档都要处理。
      //    只查 canvas 不够 —— overlayHost 被换掉时 canvas 往往还活着。
      if (S.canvas && !S.canvas.isConnected) {
        log('画布已脱离文档，重新挂载');
        resetMap();
      } else if (S.overlayHost && !S.overlayHost.isConnected) {
        log('标记层已脱离文档，重新挂载');
        resetMap();
      } else if (S.svg && !S.svg.isConnected) {
        log('路线图层已脱离文档，重建');
        S.svg = null; S.world = null; S.segs = []; S.built = false;
      }

      // ② 每轮重新定位一次。发消息会新增/替换状态面板，靠这一手兜底。
      const m = findMap();
      // 统计当前文档里可见的 OSD 容器数量
      let cCnt = 0;
      try {
        const seen = new Set();
        const walk = (w) => {
          let d = null; try { d = w.document; } catch (e) { return; }
          if (!d || seen.has(d)) return;
          seen.add(d);
          let list = [];
          try { list = Array.from(d.querySelectorAll('.openseadragon-container')); } catch (e) {}
          list.forEach(c => {
            let r = null; try { r = c.getBoundingClientRect(); } catch (e) {}
            if (r && r.width * r.height > 0) cCnt++;
          });
        };
        walk(window);
        try { walk(window.top); } catch (e) {}
        const fr = (() => { try { return (window.top || window).frames; } catch (e) { return null; } })();
        if (fr) for (let i = 0; i < fr.length && i < 40; i++) { try { walk(fr[i]); } catch (e) {} }
      } catch (e) {}
      S.diag.containers = cCnt;
      if (m) {
        const remount = !S.canvas || !S.svg || !S.world ||
                        m.doc !== S.doc || m.canvas !== S.canvas ||
                        m.overlayHost !== S.overlayHost ||
                        S.svg.parentElement !== S.canvas;
        if (remount) {
          if (m.doc !== S.doc || m.canvas !== S.canvas) {
            // 先把旧地图上的图层、三角、面板全部摘掉，否则会留下快照叠影
            unmountFrom(S.canvas);
            S.svg = null; S.world = null; S.panel = null; S.tip = null; S.hereEl = null;
            S.segs = []; S.currentMark = null; S.refEls = [];
            S.scaleApplied = false; S.built = false;
          } else if (m.overlayHost !== S.overlayHost) {
            S.refEls = [];                        // 标记层换了，参考点作废
          }
          if (!S.swept) {
            S.swept = true;
            // 只在自己是唯一实例时清扫。若存在重复实例，
            // 清扫会删掉对方的图层，两边互相拆台。
            try { if (INST.live <= 1) sweepStale(); } catch (e) {}
          }
          if (m.canvas !== S.canvas || m.overlayHost !== S.overlayHost) {
            log('地图挂载点变化 → 重新挂载（canvas ' +
                (m.canvas.clientWidth || 0) + 'x' + (m.canvas.clientHeight || 0) + '）');
          }
          S.doc = m.doc; S.container = m.container;
          S.canvas = m.canvas; S.overlayHost = m.overlayHost;
          S.fastN = 0;                       // 新打开的地图，重新给一段快速轮询
          // 换了一张地图 = 换了一个楼层，立刻读这一层自己的位置
          refreshStat();
        }
        S.diag.chosen = (m.canvas.clientWidth || 0) + 'x' + (m.canvas.clientHeight || 0);
      }

      if (S.doc && S.canvas && S.geo) {
        if (ensureLayer()) {
          ensurePanel();
          ensureHereMarker();
          if (!S.refEls.length) {
            setupRefs();
            if (S.refEls.length >= 2) attachObserver();
          }
          const changed = geoChanged();
          const rs = collectRefs();
          S.diag.refs = rs.length;
          S.diag.segs = S.segs.length;
          S.diag.k = S.k;
          S.diag.layer = (S.svg && S.svg.isConnected) ? 'OK' :
                         (S.svg ? '游离' : '无');
          S.diag.tickAt = Date.now();
          if (rs.length >= 2 && solveTransform(rs)) {
            if (S.estimated) log('标记已就位，改用精确变换');
            S.estimated = false;
            S.ready = true;
            if (changed || !S.built) buildSegments();
            else applyWorld();
            S.diag.segs = S.segs.length;
            S.diag.k = S.k;
          } else if (estimateTransform()) {
            // 还没有标记（地图正在加载）：先按整图适配摆好线，标记出来后再校正
            S.estimated = true;
            S.ready = true;
            if (!S.built) buildSegments();
            else applyWorld();
            S.diag.segs = S.segs.length;
            S.diag.k = S.k;
          }
        }
      }
    } catch (e) { warn('tick 出错', e); }
    heartbeat();
    // 还在等标记（加载期）就快一点轮询，出图时线已经画好；
    // 最多快速 40 次（约 10 秒），之后回到 800ms，避免手机上一直高频扫描
    let delay = 800;
    if (!S.refEls.length && (S.fastN = (S.fastN || 0) + 1) <= 40) delay = 250;
    setTimeout(tick, delay);
  }

  // ════════════ 启动 ════════════
  log('=== 地理路线层 ' + VERSION + ' 启动 === 实例 #' + INST.id +
      '（当前存活 ' + INST.live + ' 个）');
  try {
    window.addEventListener('pagehide', () => {
      try { HOST.__geoLive = Math.max(0, (HOST.__geoLive || 1) - 1); } catch (e) {}
      try { console.log('%c' + TAG + '#' + INST.id, 'color:#f59e0b;font-weight:bold', 'iframe 卸载'); } catch (e) {}
    });
  } catch (e) {}
  // 手动诊断：控制台执行 __geoRouteDiag() 可随时取当前状态
  // __geoRouteInternals() 只给调试/自测用，返回内部函数与状态引用。
  try {
    HOST.__geoRouteInternals = () => ({
      S, norm, stripParen, normalizeGeo, markerSignature,
      matchPlace, blockOf, readGeoSource, buildModel, panelState,
      renderPanel, ensurePanel, ensureLayer, buildSegments,
      estimateTransform, findMap, imgToRawPx, imgToCanvasPx,
      tColor: (t) => tColor(t), dashOf: (t) => dashOf(t)
    });
  } catch (e) {}
  try {
    HOST.__geoRouteDiag = () => ({
      instance: INST.id,
      liveInstances: (() => { try { return HOST.__geoLive; } catch (e) { return null; } })(),
      born: (() => { try { return HOST.__geoBorn; } catch (e) { return null; } })(),
      heartbeats: (() => { try { return HOST.__geoHB; } catch (e) { return null; } })(),
      mounted: {
        canvas: !!(S.canvas && S.canvas.isConnected),
        overlayHost: !!(S.overlayHost && S.overlayHost.isConnected),
        svg: !!(S.svg && S.svg.isConnected),
        refs: S.refEls.length,
        k: S.k, segs: S.segs.length, ready: S.ready, estimated: S.estimated
      },
      geo: !!S.geo,
      source: S.geoKind || '(none)',
      version: S.geo ? String(S.geo.version) : '',
      places: S.places.length,
      edges: S.geo ? S.geo.edges.length : 0,
      markers: Array.isArray(S.markers) ? S.markers.length : 0,
      coord: S.coordStat,
      panel: { messageId: S.panelInfo.msgId, location: S.panelInfo.loc },
      current: S.currentId,
      diag: S.diag
    });
  } catch (e) {}

  loadPrefs();
  (function waitEnv(n) {
    if (typeof getVariables !== 'function') {
      if (n > 0) return setTimeout(() => waitEnv(n - 1), 500);
      warn('getVariables 不可用：脚本没跑在酒馆助手环境里');
      return;
    }
    tick();
  })(20);
})();
